CREATE TYPE "StatusJob" AS ENUM ('PENDENTE', 'EM_PROCESSAMENTO', 'CONCLUIDO', 'FALHOU');
ALTER TABLE "Lote" ADD COLUMN "triagemConcluidaEm" TIMESTAMPTZ(3), ADD COLUMN "operadorTriagem" TEXT;
UPDATE "Lote" l SET "triagemConcluidaEm" = (SELECT MAX(m."dataHora") FROM "Equipamento" e JOIN "Movimentacao" m ON m."equipamentoId"=e.id WHERE e."loteId"=l.id AND m.destino='BAIXA_DEFINITIVA'), "operadorTriagem" = (SELECT m.responsavel FROM "Equipamento" e JOIN "Movimentacao" m ON m."equipamentoId"=e.id WHERE e."loteId"=l.id AND m.destino='BAIXA_DEFINITIVA' ORDER BY m."dataHora" DESC LIMIT 1) WHERE l."statusProcessamento"='TRIAGEM_CONCLUIDA';
CREATE TABLE "HistoricoValorEquipamento" (id TEXT PRIMARY KEY, "equipamentoId" TEXT NOT NULL REFERENCES "Equipamento"(id) ON DELETE CASCADE, "dataHora" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "valorEstimado" DECIMAL(12,2) NOT NULL, "valorRecuperacao" DECIMAL(12,2), motivo TEXT NOT NULL);
CREATE INDEX "HistoricoValorEquipamento_equipamentoId_dataHora_idx" ON "HistoricoValorEquipamento"("equipamentoId", "dataHora");
CREATE TABLE "FalhaEquipamento" (id TEXT PRIMARY KEY, "equipamentoId" TEXT NOT NULL REFERENCES "Equipamento"(id) ON DELETE CASCADE, "dataHora" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, descricao TEXT NOT NULL, custo DECIMAL(12,2));
CREATE INDEX "FalhaEquipamento_equipamentoId_dataHora_idx" ON "FalhaEquipamento"("equipamentoId", "dataHora");
CREATE TABLE "ChaveApi" (id TEXT PRIMARY KEY, hash TEXT NOT NULL UNIQUE, parceiro TEXT NOT NULL, permissoes TEXT[] NOT NULL, ativo BOOLEAN NOT NULL DEFAULT TRUE, "criadaEm" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "expiraEm" TIMESTAMP(3), "revogadaEm" TIMESTAMP(3));
CREATE INDEX "ChaveApi_parceiro_ativo_idx" ON "ChaveApi"(parceiro, ativo);
CREATE TABLE "ExecucaoAnalitica" (id TEXT PRIMARY KEY, analise TEXT NOT NULL, parametros JSONB NOT NULL, "iniciadoEm" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "concluidoEm" TIMESTAMPTZ(3), resultado JSONB);
CREATE INDEX "ExecucaoAnalitica_analise_iniciadoEm_idx" ON "ExecucaoAnalitica"(analise, "iniciadoEm");
CREATE TABLE "JobRelatorio" (id TEXT PRIMARY KEY, tipo TEXT NOT NULL, status "StatusJob" NOT NULL DEFAULT 'PENDENTE', parametros JSONB NOT NULL, resultado JSONB, erro TEXT, arquivo TEXT, tentativas INTEGER NOT NULL DEFAULT 0, "criadoEm" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "atualizadoEm" TIMESTAMPTZ(3) NOT NULL);
CREATE INDEX "JobRelatorio_status_criadoEm_idx" ON "JobRelatorio"(status, "criadoEm");
